function TicketDetail({ item, es, onClose }: { item: Ticket; es: boolean; onClose: () => void }) {
  const [ticketTab, setTicketTab] = useState("detail");
  const [ticketAction, setTicketAction] = useState("");
  const [responseText, setResponseText] = useState("");
  const [showSendChooser, setShowSendChooser] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCcFields, setShowCcFields] = useState(false);
  const [finalizeOnSend, setFinalizeOnSend] = useState(false);
  const leftTabs: Array<[string,string,LucideIcon]> = [["detail",es?"Detalle del caso":"Case details",Info],...(item.kind==="pqrsf"?[["pqrsf",es?"Información PQRSF":"PQRSF information",ClipboardList] as [string,string,LucideIcon]]:[])];
  const send = () => { if (responseText.trim()) setShowSendChooser(true); };
  return <div className="demo-ticket-response"><header className="ticket-response-header"><div><small>ORBIT / {item.id}</small><h3>{es?"Respuesta de ticket":"Ticket response"}</h3></div><div className="ticket-header-actions"><span>{item.status}</span><button onClick={onClose}><X size={16}/>{es?"Salir":"Exit"}</button></div></header><div className="demo-ticket-response-layout"><section className="demo-ticket-case-panel"><div className="case-person"><span>LM</span><div><b>Laura Méndez</b><small>laura.mendez@empresa.co</small></div><em>{item.id}</em></div><div className="modal-tabs case-tabs">{leftTabs.map(([key,label,Icon])=><button key={key} className={ticketTab===key?"active":""} onClick={()=>setTicketTab(key)}><Icon size={15}/>{label}</button>)}</div>{ticketTab==="pqrsf"?<div className="case-fields"><label>{es?"Tipo de solicitud":"Request type"}<select><option>Petición</option></select></label><label>{es?"Canal de recepción":"Reception channel"}<input value="Formulario web" readOnly/></label><label>{es?"Fecha límite de respuesta":"Response deadline"}<input value="30 SEP 2026" readOnly/></label><label>{es?"Tratamiento de datos":"Data processing"}<input value="Autorizado" readOnly/></label></div>:<><div className="case-fields"><label>{es?"Asunto":"Subject"}<input defaultValue={item.title}/></label><div><label>{es?"Estado":"Status"}<select defaultValue={item.status}><option>{item.status}</option></select></label><label>{es?"Prioridad":"Priority"}<select defaultValue={item.priority}><option>{item.priority}</option></select></label></div><label>{es?"Responsable":"Owner"}<select defaultValue={item.owner}><option>{item.owner}</option></select></label><label>{es?"Área / categoría":"Area / category"}<select defaultValue={item.area}><option>{item.area}</option></select></label></div><article className="case-description"><b>{es?"Descripción del caso":"Case description"}</b><p>{es?"El usuario reporta una incidencia que afecta la continuidad de la operación. Solicita validación prioritaria del equipo.":"The user reports an incident affecting operations and requests priority validation."}</p></article></>}</section><section className="demo-ticket-composer-panel"><header><div><MessageSquareDiff size={18}/><div><b>{es?"Conversación":"Conversation"}</b><small>{es?"Actividad y respuesta del caso":"Case activity and response"}</small></div></div><button onClick={()=>setTicketTab(ticketTab==="timeline"?"detail":"timeline")}><History size={16}/>{es?"Trazabilidad":"History"}</button></header>{ticketTab==="timeline"?<div className="demo-timeline ticket-history"><p><b>09:04</b>{es?"Asignado al equipo responsable":"Assigned to responsible team"}</p><p><b>08:42</b>{es?"Clasificación automática confirmada":"Automatic classification confirmed"}</p><p><b>08:21</b>{es?"Ticket creado desde WhatsApp":"Ticket created from WhatsApp"}</p></div>:<div className="conversation-scroll"><article className="conversation-event"><span>LM</span><div><header><b>Laura Méndez</b><small>08:21</small></header><p>{es?"El equipo presenta intermitencia desde esta mañana y no permite completar la operación.":"The equipment has been intermittent since this morning."}</p><small>{es?"Enviado desde WhatsApp":"Sent from WhatsApp"}</small></div></article><article className="conversation-event agent-event"><span>SR</span><div><header><b>{item.owner}</b><small>09:06</small></header><p>{es?"Estamos validando la conectividad y los registros del terminal. Te informaremos aquí cualquier avance.":"We are checking connectivity and terminal logs."}</p></div></article></div>}<form className="ticket-composer" onSubmit={(event)=>{event.preventDefault();send();}}>{showCcFields&&<div className="composer-cc"><input aria-label="CC" placeholder="CC: correo1@ej.com, correo2@ej.com"/><input aria-label="CCO" placeholder="CCO: correo1@ej.com, correo2@ej.com"/></div>}{showSendChooser&&<div className="composer-send-chooser"><b>{es?"¿Cómo envías este mensaje?":"How do you send this message?"}</b><button type="button" onClick={()=>{setShowSendChooser(false);setResponseText("");}}>{es?"Pública":"Public"}</button><button type="button" className="internal" onClick={()=>{setShowSendChooser(false);setResponseText("");}}>{es?"Interna":"Internal"}</button><button type="button" onClick={()=>setShowSendChooser(false)}>{es?"Cancelar":"Cancel"}</button></div>}<div className="composer-settings"><label><input type="checkbox" checked={finalizeOnSend} onChange={(event)=>setFinalizeOnSend(event.target.checked)}/>{es?"Finalizar ticket al enviar (solo respuesta pública)":"Finish ticket when sending (public reply only)"}</label><button type="button" onClick={()=>setShowCcFields(!showCcFields)}>{showCcFields?(es?"Ocultar CC/CCO":"Hide CC/BCC"):'+ CC/CCO'}</button></div><div className="composer-input-row"><div className="composer-plus-wrap"><button type="button" className={`composer-plus ${showActionMenu?"active":""}`} title={es?"Más opciones":"More options"} onClick={()=>setShowActionMenu(!showActionMenu)}><Plus size={20}/></button>{showActionMenu&&<div className="composer-action-menu"><button type="button"><Paperclip size={16}/><span><b>{es?"Adjuntar archivo":"Attach file"}</b><small>{es?"Imagen o PDF, máx. 1 MB":"Image or PDF, max. 1 MB"}</small></span></button><button type="button"><FileText size={16}/><span><b>{es?"Plantilla rápida":"Quick template"}</b><small>{es?"Inserta una respuesta predefinida":"Insert a predefined response"}</small></span></button><button type="button"><UserPlus size={16}/><span><b>{es?"Mencionar a un usuario":"Mention a user"}</b><small>{es?"Escala el caso a alguien puntual":"Escalate to a specific user"}</small></span></button><button type="button"><AlertTriangle size={16}/><span><b>{es?"Marcar como importante":"Mark as important"}</b><small>{es?"Resalta el caso en la tabla":"Highlight the case in the table"}</small></span></button><button type="button" onClick={()=>{setShowActionMenu(false);setTicketAction("escalate");}}><ArrowLeftRight size={16}/><span><b>{es?"Escalar o pasar a otra área":"Escalate or transfer"}</b><small>{es?"Pide apoyo o transfiere el caso":"Request support or transfer the case"}</small></span></button><button type="button" onClick={()=>{setShowActionMenu(false);setTicketAction("pause");}}><History size={16}/><span><b>{es?"Pausar ticket":"Pause ticket"}</b><small>{es?"Cambia el estado a En pausa":"Change status to Paused"}</small></span></button></div>}</div><textarea rows={1} value={responseText} onChange={(event)=>{setResponseText(event.target.value);if(!event.target.value.trim())setShowSendChooser(false);}} placeholder={es?"Escribe un mensaje… Enter para enviar, Shift+Enter salto de línea":"Write a message… Enter to send, Shift+Enter for a new line"}/><button type="submit" className="composer-send" disabled={!responseText.trim()} title={es?"Enviar":"Send"}><Send size={18}/></button></div>{ticketAction&&<TicketActionBox action={ticketAction} es={es} onClose={()=>setTicketAction("")}/>}</form></section></div></div>;
}

function TicketActionBox({ action, es, onClose }: { action: string; es: boolean; onClose: () => void }) {
  const titles: Record<string,string>={assign:es?"Asignar ticket":"Assign ticket",escalate:es?"Escalar ticket":"Escalate ticket",pause:es?"Pausar ticket":"Pause ticket",finish:es?"Finalizar ticket":"Finish ticket"};
  return <div className="inline-action-box"><h4>{titles[action]}</h4><p>{action==="escalate"?(es?"Solicita apoyo a otra área o transfiere la responsabilidad.":"Request support or transfer ownership."):action==="pause"?(es?"Selecciona motivo y fecha de reanudación.":"Select reason and resume date."):(es?"Confirma la información antes de continuar.":"Confirm information before continuing.")}</p><label>{es?"Destino o motivo":"Target or reason"}<select><option>{action==="escalate"?"Infraestructura":action==="pause"?"Esperando proveedor":"Laura Méndez"}</option></select></label><label>{es?"Nota interna":"Internal note"}<textarea rows={3}/></label><div className="form-actions"><button onClick={onClose}>{es?"Cancelar":"Cancel"}</button><button className="demo-primary" onClick={onClose}>{es?"Confirmar":"Confirm"}</button></div></div>;
}

