function MaintenanceDetail({ item, es }: { item: Maintenance; es: boolean }) {
  const [executing, setExecuting] = useState(false);
  return <div className="demo-detail wide-detail"><small>ORBIT / {item.id}</small><h3>{item.title}</h3><div className="ticket-actions"><button className="finish" onClick={()=>setExecuting(!executing)}>{es?"Ejecutar mantenimiento":"Run maintenance"}</button></div><div className="detail-meta"><span><b>{es?"Estado":"Status"}</b>{item.status}</span><span><b>{es?"Responsable":"Owner"}</b>{item.owner}</span><span><b>{es?"Sede":"Site"}</b>{item.site}</span><span><b>{es?"Progreso":"Progress"}</b>{item.progress}%</span></div>{executing?<section className="maintenance-execution"><h4>{es?"Ejecutar mantenimiento":"Run maintenance"}</h4>{["Inspección visual","Prueba funcional","Limpieza de equipo","Validación de red","Registro de evidencias"].map((label,i)=><label key={label}><input type="checkbox" defaultChecked={i<2}/><span>{label}</span><select><option>{i<2?"Conforme":"Pendiente"}</option></select></label>)}<div className="signature-grid"><button><b>{es?"Firma del responsable":"Owner signature"}</b><span>{es?"Tocar para firmar":"Tap to sign"}</span></button><button><b>{es?"Firma de sede":"Site signature"}</b><span>{es?"Tocar para firmar":"Tap to sign"}</span></button></div><div className="form-actions"><button onClick={()=>setExecuting(false)}>{es?"Guardar borrador":"Save draft"}</button><button className="demo-primary" onClick={()=>setExecuting(false)}>{es?"Completar ejecución":"Complete execution"}</button></div></section>:<><section><h4>Checklist</h4><p>✓ {es?"Inspección visual":"Visual inspection"}</p><p>✓ {es?"Prueba funcional":"Functional test"}</p><p>○ {es?"Registro de evidencias":"Evidence record"}</p></section><section><h4>{es?"Firmas":"Signatures"}</h4><p>{es?"Responsable técnico · pendiente":"Technical owner · pending"}</p></section></>}</div>;
}
